                        "in": "query"
                    },
                    {
                        "name": "created_from",
                        "schema": {
                            "type": "string",
                            "format": "date-time"
                        },
                        "description": "Create from date time (ISO 8601 format)",
                        "required": false,
                        "in": "query"
                    },
                    {
                        "name": "created_to",
                        "schema": {
                            "type": "string",
                            "format": "date-time"
                        },
                        "description": "Create to date time (ISO 8601 format)",
                        "required": false,
                        "in": "query"
                    }
                ],
                "responses": {
                    "200": {
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/BalanceRecordListResponse"
                                }
                            }
                        },
                        "description": "Successful operation"
                    }
                }
            }
