                        "required": false,
                        "in": "header"
                    },
                    {
                        "name": "lang",
                        "schema": {
                            "type": "string",
                            "enum": [
                                "et",
                                "en",
                                "all"
                            ],
                            "example": "en",
                            "default": "all"
                        },
                        "description": "Language code",
                        "required": false,
                        "in": "query"
                    },
                    {
                        "name": "valid_on",
                        "schema": {
                            "type": "string",
                            "format": "date",
                            "example": "2025-01-01"
                        },
                        "description": "Date in ISO 8601 format (YYYY-MM-DD)",
                        "required": false,
                        "in": "query"
                    }
                ],
                "responses": {
                    "200": {
                        "content": {
                            "application/json": {
                                "schema": {
                                    "type": "array",
                                    "items": {
                                        "type": "object",
                                        "properties": {
                                            "id": {
                                                "type": "string",
                                                "example": "I",
                                                "description": "Unique identifier"
                                            },
                                            "sort": {
                                                "type": "integer",
                                                "example": 1,
                                                "description": "Sort order."
                                            },
                                            "valid_from": {
                                                "type": "string",
                                                "format": "date",
                                                "example": "2000-01-01",
                                                "description": "The date from which the packing group is valid."
                                            },
                                            "valid_to": {
                                                "type": "string",
                                                "format": "date",
                                                "nullable": true,
                                                "example": null,
                                                "description": "The date until which the packing group is valid. Null if indefinitely valid."
                                            },
                                            "name": {
                                                "oneOf": [
                                                    {
                                                        "type": "object",
                                                        "additionalProperties": {
                                                            "type": "string",
                                                            "description": "Name in different languages (if paramtere lang=all (default))"
                                                        },
                                                        "description": "Name as a dictionary with language codes as keys (if lang=all (default))",
                                                        "example": {
                                                            "en": "Packing Group I - high hazard substances (in English)",
                                                            "et": "Packing Group I - high hazard substances (in Estonian)"
                                                        }
                                                    },
                                                    {
                                                        "type": "string",
                                                        "description": "Name as a simple string (if lang=et or lang=en)",
                                                        "example": "Packing Group I - high hazard substances"
                                                    }
                                                ]
                                            }
                                        }
                                    }
                                }
                            }
                        },
                        "description": "Successful operation"
                    }
                }
            }
